// src/components/HubspotForms.js
import { useEffect } from "react";

const HubspotForms = ({ portalId, formId, region, targetId }) => {
  useEffect(() => {
    const scriptUrl = "//js.hsforms.net/forms/embed/v2.js";

    // Check if script already exists
    let script = document.querySelector(`script[src="${scriptUrl}"]`);

    // If not, create and append it
    if (!script) {
      script = document.createElement("script");
      script.src = scriptUrl;
      script.async = true;
      document.head.appendChild(script);
    }

    const renderForm = () => {
      if (window.hbspt && window.hbspt.forms) {
        const targetElement = document.getElementById(targetId);
        if (targetElement) {
          targetElement.innerHTML = ""; // clear old form
          window.hbspt.forms.create({
            portalId,
            formId,
            region,
            target: `#${targetId}`,
          });
        }
      } else {
        console.error("HubSpot forms not available yet.");
      }
    };

    // If script already loaded, render immediately
    if (window.hbspt && window.hbspt.forms) {
      renderForm();
    } else {
      script.onload = renderForm;
    }

    // Cleanup on unmount
    return () => {
      const targetElement = document.getElementById(targetId);
      if (targetElement) {
        targetElement.innerHTML = "";
      }
    };
  }, [portalId, formId, region, targetId]);

  return <div id={targetId}></div>;
};

export default HubspotForms;
